//! Runs tests/fixtures/error_contract.json, generated by
//! scripts/error-contract/sync.ts from the backend's error catalog
//! (keenable-backend-ts docs/error-catalog.json) plus the bodies servers sent
//! before error format v1. The other SDKs test the same file.

use std::time::Duration;

use serde_json::Value;

use super::conformance::exposed_text;
use super::server::{start, Reply, Script};
use super::*;
use crate::Error;

fn contract() -> Vec<Value> {
    load_fixture("error_contract.json")["cases"]
        .as_array()
        .unwrap()
        .clone()
}

fn reply(case: &Value, body: &Value) -> Reply {
    let mut reply = Reply::new(case["status"].as_u64().unwrap() as u16, &body.to_string());
    for (k, v) in case["headers"].as_object().unwrap() {
        reply = reply.header(k, v.as_str().unwrap());
    }
    reply
}

fn kind_of(err: &Error) -> &'static str {
    match err {
        Error::Auth(_) => "auth",
        Error::RateLimit(_) => "rate_limit",
        Error::InsufficientCredits(_) => "insufficient_credits",
        Error::Api(_) => "api",
        _ => "other",
    }
}

#[test]
fn the_fixture_is_the_same_in_every_sdk() {
    same_in_every_sdk("error_contract.json", "tests/fixtures/error_contract.json");
}

#[tokio::test]
async fn backend_error_bodies_parse_into_typed_errors() {
    let mut failures = Vec::new();
    for case in contract() {
        let server = start(Script::Replies(vec![reply(&case, &case["body"])])).await;
        let err = keyed(&server).search("q").await.unwrap_err();
        let want = &case["expect"];
        let name = case["name"].as_str().unwrap();
        let api = err.api_error().cloned().unwrap();
        let mut problems = Vec::new();
        let s = |v: &Value| v.as_str().map(str::to_string);
        if kind_of(&err) != want["kind"] {
            problems.push(format!("kind {}", kind_of(&err)));
        }
        if u64::from(api.status_code) != case["status"].as_u64().unwrap()
            || api.code != s(&want["code"])
            || api.error != s(&case["body"]["error"])
            || api.error_type != want["type"].as_str().unwrap()
            || api.fix != s(&want["fix"])
            || api.param != s(&want["param"])
            || api.request_id != s(&want["request_id"])
            || api.retryable != want["retryable"].as_bool()
        {
            problems.push(format!("fields {api:?}"));
        }
        let wait = want["retry_after_seconds"]
            .as_f64()
            .map(Duration::from_secs_f64);
        if api.retry_after != wait {
            problems.push(format!("retry after {:?}, want {wait:?}", api.retry_after));
        }
        let want_limit = want["limit"].as_object().map(|l| crate::RateLimitInfo {
            scope: s(&l["scope"]),
            window: s(&l["window"]),
            max: l["max"].as_u64(),
            resets_at: s(&l["resets_at"]),
        });
        if api.limit != want_limit {
            problems.push(format!("limit {:?}, want {want_limit:?}", api.limit));
        }
        for a in want["absent"].as_array().unwrap() {
            let a = a.as_str().unwrap();
            if !a.is_empty() && exposed_text(&err).iter().any(|t| t.contains(a)) {
                problems.push(format!("{a:?} exposed"));
            }
        }
        let msg = err.to_string();
        if !msg.contains(want["message_contains"].as_str().unwrap()) || msg.contains("Docs:") {
            problems.push(format!("message {msg:?}"));
        }
        let tail = format!(
            " (code: {}) (request_id: {}) ({})",
            want["code"].as_str().unwrap_or(""),
            want["request_id"].as_str().unwrap_or(""),
            err.sdk_code()
        );
        if !msg.ends_with(&tail) {
            problems.push(format!("{msg:?} does not end with {tail:?}"));
        }
        if !problems.is_empty() {
            failures.push(format!("{name}: {}", problems.join("; ")));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[tokio::test]
async fn a_server_without_type_gets_the_catalog_type_derived() {
    let mut failures = Vec::new();
    for case in contract() {
        let Some(body) = case["body"].as_object() else {
            continue;
        };
        if !body.contains_key("type") {
            continue;
        }
        let mut body = body.clone();
        body.remove("type");
        let server = start(Script::Replies(vec![reply(&case, &Value::Object(body))])).await;
        let err = keyed(&server).search("q").await.unwrap_err();
        let got = err
            .api_error()
            .map(|a| a.error_type.clone())
            .unwrap_or_default();
        let want = &case["expect"];
        if got != want["type"].as_str().unwrap()
            || matches!(err, Error::Auth(_)) != (want["kind"] == "auth")
        {
            failures.push(format!("{}: derived {got}, {err:?}", case["name"]));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[tokio::test]
async fn the_type_the_api_sends_is_kept_as_sent() {
    let server = start(Script::Replies(vec![Reply::new(
        400,
        r#"{"error":"x","type":"new_error"}"#,
    )]))
    .await;
    let err = keyed(&server).search("q").await.unwrap_err();
    assert_eq!(err.api_error().unwrap().error_type, "new_error");
}
